from pathlib import Path
import datetime, hashlib, json, math, os, statistics, struct, subprocess
root=Path(__file__).resolve().parent
out=root/'timing'; out.mkdir(exist_ok=False)
plan=json.loads((root/'plan.json').read_text())
def sha(p):
    with Path(p).open('rb') as f: return hashlib.file_digest(f,'sha256').hexdigest()
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def contention():
    cmd="Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '^(llmx|llama|candidate-compare|control-compare|plain$|spans$|fault$|oracle$|cl$|cmake$|ninja$|g\\+\\+$)' } | Select-Object Id,ProcessName | ConvertTo-Json -Compress"
    return subprocess.check_output(['powershell','-NoProfile','-Command',cmd],text=True).strip()
state={'status':'preparing','pid':os.getpid(),'started':now(),'plan':plan,'plan_sha256':sha(root/'plan.json'),'runner_sha256':sha(__file__),'manifest_sha256':sha(root/'manifest.json'),'rows':[]}
def save(): (out/'results.json').write_text(json.dumps(state,indent=2)+'\n')
save()
try:
    for f,v in json.loads((root/'manifest.json').read_text()).items(): assert sha(root/f)==v['sha256'],f
    assert sha(plan['model'])==plan['model_sha256']
    assert sha(plan['tokens'])==plan['tokens_sha256']
    expected_vector=None
    state['status']='running';save()
    for index,arms in enumerate(plan['order']):
        pair=index-1
        for arm in arms:
            active=contention();assert not active,active
            name=f'pair{pair}-{arm}'
            command=[str(root/(arm+'.exe')),plan['model'],plan['tokens'],str(out/(name+'.f32'))]
            row={'name':name,'pair':pair,'arm':arm,'command':command,'started':now(),'before':active,'status':'running'}
            state['rows'].append(row);save();print('START',name,flush=True)
            with (out/(name+'.stdout')).open('wb') as stdout,(out/(name+'.stderr')).open('wb') as stderr:
                p=subprocess.Popen(command,stdout=stdout,stderr=stderr);row['pid']=p.pid;save()
                try: rc=p.wait(timeout=300)
                except subprocess.TimeoutExpired:
                    p.kill();p.wait();row['status']='timeout';save();raise
            row.update(returncode=rc,completed=now());assert rc==0,(name,rc)
            active=contention();row['after']=active;assert not active,active
            raw=(out/(name+'.f32')).read_bytes();assert len(raw)==151936*4
            assert all(math.isfinite(v[0]) for v in struct.iter_unpack('<f',raw))
            if expected_vector is None: expected_vector=raw
            assert raw==expected_vector,name+' final vector mismatch'
            row['final_vector_sha256']=hashlib.sha256(raw).hexdigest()
            doc=json.loads((out/(name+'.stdout')).read_bytes())
            assert doc['threads']==6
            assert all(math.isfinite(doc[x]) and doc[x]>0 for x in ['pp_ms','tg_ms'])
            if arm=='spans':
                for phase,count in [('pp',plan['expected_pp_dispatches']),('tg',plan['expected_tg_dispatches'])]:
                    assert len(doc[phase])==count,(phase,len(doc[phase]),count)
                    for rec in doc[phase]:
                        assert len(rec)==13
                        assert all(0<=a<=b<=rec[0] for a,b in zip(rec[1::2],rec[2::2]))
                    assert sum(x[0] for x in doc[phase])/1e6 <= doc[phase+'_ms']
            row.update(status='pass',pp_ms=doc['pp_ms'],tg_ms=doc['tg_ms'],fnv64=doc['final_vector_fnv64'],stdout_sha256=sha(out/(name+'.stdout')),stderr_sha256=sha(out/(name+'.stderr')));save();print('PASS',name,doc['pp_ms'],doc['tg_ms'],flush=True)
    summary={}
    for phase in ['pp_ms','tg_ms']:
        samples={arm:[x[phase] for x in state['rows'] if x['pair']>=0 and x['arm']==arm] for arm in ['plain','spans']}
        summary[phase]={arm:dict(samples=v,mean=statistics.mean(v),median=statistics.median(v)) for arm,v in samples.items()}
        summary[phase]['spans_vs_plain_mean_percent']=100*(statistics.mean(samples['spans'])/statistics.mean(samples['plain'])-1)
        summary[phase]['paired_percent']=[100*(b/a-1) for a,b in zip(samples['plain'],samples['spans'])]
    state.update(status='pass',completed=now(),summary=summary);save();print(json.dumps(summary,indent=2),flush=True)
except BaseException as e:
    state.update(status='failed',completed=now(),error=repr(e));save();raise

